{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    data = case.get("payload") if "payload" in case else case
    if not isinstance(data, dict):
        raise ValueError("payload must be an object")
    if "segments" not in data or "budget" not in data:
        raise ValueError("missing required field")

    segments = data["segments"]
    budget = data["budget"]
    if not isinstance(segments, list) or not segments:
        raise ValueError("segments must be a non-empty list")
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise ValueError("budget must be an integer")

    names = []
    importances = []
    allocations = []
    capacities = []
    seen_names = set()

    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("each segment must be an object")
        required = ("name", "importance", "minimum", "capacity")
        if any(field not in segment for field in required):
            raise ValueError("segment is missing a required field")

        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]

        if not isinstance(name, str) or not name or name in seen_names:
            raise ValueError("segment names must be unique non-empty strings")
        if any(isinstance(value, bool) or not isinstance(value, int)
               for value in (importance, minimum, capacity)):
            raise ValueError("segment statistics must be integers")
        if importance < 0 or minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment bounds")

        seen_names.add(name)
        names.append(name)
        importances.append(importance)
        allocations.append(minimum)
        capacities.append(capacity)

    minimum_total = sum(allocations)
    capacity_total = sum(capacities)
    if budget < minimum_total or budget > capacity_total:
        raise ValueError("budget is infeasible")

    remaining = budget - minimum_total
    while remaining:
        best_index = None
        for index in range(len(allocations)):
            if allocations[index] >= capacities[index]:
                continue
            if best_index is None:
                best_index = index
                continue
            # Compare importance / next_position exactly, preserving source order on ties.
            left = importances[index] * (allocations[best_index] + 1)
            right = importances[best_index] * (allocations[index] + 1)
            if left > right:
                best_index = index
        allocations[best_index] += 1
        remaining -= 1

    name_mapping = {names[index]: allocations[index] for index in range(len(names))}
    return {
        "allocations": allocations,
        "name_mapping": name_mapping,
        "total": sum(allocations),
    }
